import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final long MOD = 1000000007;
        long p = sc.nextLong();
        long k = sc.nextLong();
        long result = 1;

        if (k != 0 && k != 1) {
            int[] visited = new int[(int) p + 1];
            int[] cycleCount = new int[(int) p + 1];

            // Helper method for exploring cycles
            exploreCycle(0, 0, p, k, visited, cycleCount);

            for (int i = 1; i < p; i++) {
                if (visited[i] == 0) {
                    exploreCycle(i, 0, p, k, visited, cycleCount);
                }
            }

            for (int i = 1; i <= p; i++) {
                for (int j = 1; j <= cycleCount[i]; j++) {
                    result = (result * (cycleCount[i] * i + 1)) % MOD;
                }
            }
        } else if (k == 0) {
            for (int i = 1; i < p; i++) {
                result = (result * p) % MOD;
            }
        } else if (k == 1) {
            for (int i = 1; i <= p; i++) {
                result = (result * p) % MOD;
            }
        }

        System.out.println(result);
        sc.close();
    }

    private static void exploreCycle(int start, int depth, long p, long k, int[] visited, int[] cycleCount) {
        if (visited[start] == 1) {
            cycleCount[depth]++;
            return;
        }
        visited[start] = 1;
        long next = (start * k) % p;
        exploreCycle((int) next, depth + 1, p, k, visited, cycleCount);
    }
}

